(window.RYADOM_I18N = window.RYADOM_I18N || {})["fr"] = {"strings":{"Разделы":"Rubriques","Сегодня":"Aujourd’hui","Мой дневник":"Mon journal","Места":"Lieux","Игры":"Jeux","Практики":"Exercices","Обо мне":"À propos de moi","Ты можешь идти в своём темпе.":"Tu peux avancer à ton rythme.","Здесь нет правильных ответов и обязательных серий дней.":"Ici, pas de bonnes réponses ni de séries de jours obligatoires.","Пространство для себя":"Un espace pour soi","Профиль":"Profil","Как ты сегодня?":"Comment vas-tu aujourd’hui ?","Можно честно. Начнём с того, что есть сейчас.":"Tu peux être honnête. Partons de ce qui est là maintenant.","С чего начать":"Par où commencer","Поговорить":"Parler","Своими словами, без правил":"Avec tes mots, sans règles","Потренировать разговор":"S’entraîner à une conversation","Начальник, мама, отказ, извинение":"Patron, maman, refuser, s’excuser","Подобрать практику":"Choisir un exercice","Подходящую сейчас":"Adapté à maintenant","Рядом":"Ryadom","На твоей стороне":"De ton côté","Напиши, что происходит…":"Écris ce qui se passe…","Написать сообщение":"Écrire un message","Продиктовать сообщение":"Dicter un message","Отправить":"Envoyer","Озвучивать ответы":"Lire les réponses à voix haute","На сегодня":"Pour aujourd’hui","Достаточно одного маленького шага":"Un petit pas suffit","Не нужно исправлять весь день целиком.":"Pas besoin de réparer toute la journée.","Твоё пространство":"Ton espace","Разговоры и отметки сохраняются только на этом устройстве.":"Les conversations et les relevés restent uniquement sur cet appareil.","Последняя отметка":"Dernier relevé","Пока нет":"Pas encore","Открыть дневник →":"Ouvrir le journal →","✦ ПРАКТИКА ДНЯ":"✦ EXERCICE DU JOUR","После трудного разговора":"Après une conversation difficile","4–6 минут · пройти →":"4–6 minutes · commencer →","Только о тебе и твоём состоянии":"Seulement toi et ton état","Разговоры, ощущения и места, в которых прошёл твой день. Игровые истории хранятся отдельно.":"Conversations, ressentis et lieux de ta journée. Les histoires des jeux sont gardées à part.","Календарь дня ↓":"Calendrier ↓","7 дней":"7 jours","30 дней":"30 jours","Как сегодня внутри?":"Comment ça va à l’intérieur aujourd’hui ?","Четыре отдельные отметки от 0 до 4. Это твои ощущения, а не медицинская оценка.":"Quatre notes de 0 à 4. Ce sont tes ressentis, pas une évaluation médicale.","Тревога":"Anxiété","совсем нет":"pas du tout","очень сильно":"très fort","Грусть":"Tristesse","Беспокойство":"Agitation","Спокойствие":"Calme","Что запомнилось сегодня?":"Qu’as-tu retenu de la journée ?","(необязательно)":"(facultatif)","Можно отмечать раз в день. Сегодняшнюю отметку можно изменить.":"Un relevé par jour. Celui d’aujourd’hui peut être modifié.","Сохранить отметку":"Enregistrer","Сильная тревога":"Forte anxiété","Нет отметок":"Aucun relevé","Сильная грусть":"Forte tristesse","Много спокойствия":"Beaucoup de calme","Как менялось состояние":"L’évolution de ton état","Каждая точка — твоя отметка за день. Пропуски не считаются нулём.":"Chaque point est ton relevé d’un jour. Les jours manqués ne comptent pas pour zéro.","Пока нет точек на графике. Поставь первую отметку выше.":"Pas encore de points sur le graphique. Fais ton premier relevé plus haut.","0 — совсем нет":"0 — pas du tout","4 — очень сильно":"4 — très fort","Что можно заметить":"Ce qu’on peut remarquer","После трёх отметок здесь появится короткое наблюдение. Пропущенные дни не учитываются.":"Après trois relevés, une courte observation apparaîtra ici. Les jours manqués ne comptent pas.","Что помогает именно тебе":"Ce qui t’aide, toi","Когда ты попробуешь практику и оценишь её, здесь появятся твои наблюдения.":"Quand tu auras essayé et noté un exercice, tes observations apparaîtront ici.","Стереть дневник":"Effacer le journal","Календарь дня":"Calendrier","Предыдущий месяц":"Mois précédent","Следующий месяц":"Mois suivant","Пн":"Lu","Вт":"Ma","Ср":"Me","Чт":"Je","Пт":"Ve","Сб":"Sa","Вс":"Di","Синяя точка — разговор, зелёная — место. Цвет дня — настроение; другие точки — отметка ощущений. Игровые события сюда не попадают.":"Point bleu : conversation ; vert : lieu. Couleur du jour : humeur ; autres points : relevé des ressentis. Les jeux n’apparaissent pas ici.","Пока нет записей за этот день. Можно добавить место, которое тебе запомнилось.":"Pas encore d’entrée ce jour-là. Tu peux ajouter un lieu dont tu te souviens.","Места этого дня":"Lieux du jour","Пока пусто":"Vide pour l’instant","Добавь посещённое место. Приложение не отслеживает перемещения автоматически.":"Ajoute un lieu visité. L’appli ne suit pas tes déplacements automatiquement.","＋ Добавить место":"＋ Ajouter un lieu","Места записываешь только ты. Они остаются на этом устройстве и не привязаны к игровому прогрессу.":"Toi seul·e enregistres les lieux. Ils restent sur cet appareil et ne sont pas liés aux jeux.","Дневник хранится только на этом устройстве. Посещённые места добавляешь только ты; автоматического отслеживания перемещений нет.":"Le journal reste uniquement sur cet appareil. Toi seul·e ajoutes les lieux visités ; aucun suivi automatique.","Место для этого момента":"Un lieu pour ce moment","Куда под настроение?":"Où aller selon ton humeur ?","Иногда помогает сменить обстановку. Выбери, чего хочется сейчас, и посмотри места поблизости.":"Changer de cadre aide parfois. Choisis ce dont tu as envie et regarde les lieux proches.","Какое настроение?":"Quelle humeur ?","☁ Грустно":"☁ Triste","◌ Тревожно":"◌ Anxieux","♡ Романтично":"♡ Romantique","✷ Весело":"✷ Joyeux","✿ Спокойно":"✿ Calme","◇ Хочется нового":"◇ Envie de nouveau","☕ Устало":"☕ Fatigué","↗ Хочется общения":"↗ Envie de compagnie","Можно выбрать настроение, а потом указать город или разрешить определить примерное местоположение.":"Choisis une humeur, puis indique une ville ou autorise la position approximative.","Где искать?":"Où chercher ?","Геолокация запрашивается только по нажатию и не записывается в дневник. Поиск по названию города показывает места около его центра.":"La position n’est demandée qu’au toucher et n’est pas enregistrée dans le journal. La recherche par ville montre des lieux près du centre.","⌖ Рядом со мной":"⌖ Près de moi","Или город / район":"Ou ville / quartier","Например, Тбилиси":"par ex. Lyon","Найти":"Chercher","Выбери настроение и место поиска.":"Choisis une humeur et où chercher.","Место найдётся":"Un lieu va se trouver","Выбери настроение и нажми «Рядом со мной» или введи город. Любимые места из дневника появятся здесь первыми.":"Choisis une humeur et touche « Près de moi » ou saisis une ville. Tes lieux favoris du journal apparaîtront en premier.","Порядок: сначала любимые, затем подходящие места по расстоянию. Рейтинги и популярность в соцсетях пока не доступны — мы не подменяем их количеством посещений.":"Ordre : d’abord les favoris, puis les lieux adaptés par distance. Les notes et la popularité sur les réseaux ne sont pas encore disponibles ; on ne les remplace pas par des visites.","Моё: что я люблю":"À moi : ce que j’aime","Работает без интернета. Если поиск мест недоступен, подсказки берутся отсюда и из раздела «Обо мне».":"Fonctionne hors ligne. Si la recherche n’est pas disponible, les idées viennent d’ici et de « À propos de moi ».","Пока пусто. Добавь любимое место, блюдо или занятие: подсказки станут точнее.":"Vide pour l’instant. Ajoute un lieu, un plat ou une activité préférés : les idées seront plus justes.","Что добавить":"Quoi ajouter","Еда":"Repas","Место":"Lieu","Занятие":"Activité","например: кофейня у реки":"par ex. café au bord de l’eau","Название или описание":"Nom ou description","Добавить":"Ajouter","Новые места: данные участников OpenStreetMap через Photon. Сведения могут быть неполными.":"Nouveaux lieux : données des contributeurs d’OpenStreetMap via Photon. Les informations peuvent être incomplètes.","Интерактивные истории":"Histoires interactives","Игры про жизнь":"Jeux sur la vie","Герои, разговоры и решения, после которых меняется история.":"Des personnages, des conversations et des choix qui changent l’histoire.","Сюжетная игра · одна неделя":"Jeu narratif · une semaine","Тихий город: неделя до ответа":"Ville tranquille : une semaine avant de répondre (en russe)","Письмо о работе в другом городе, мама, папа, подруга и восемь слотов времени. На всё не хватит — и каждая встреча оставит след.":"Une offre de travail dans une autre ville, maman, papa, une amie et huit créneaux. Impossible de tout faire — et chaque rencontre laisse une trace.","Одна неделя, восемь слотов, пять единиц сил":"Une semaine, huit créneaux, cinq unités d’énergie","Начать историю →":"Commencer l’histoire →","Тренажёры разговоров":"Entraînements à la conversation","Квесты, где выбор слов меняет ход разговора. Опираются на известные методики общения.":"Des quêtes où le choix des mots change la conversation. Basées sur des méthodes de communication connues. Pour l’instant en russe uniquement.","КВЕСТ · 6 ШАГОВ · 2 СТИЛЯ":"QUÊTE · 6 ÉTAPES · 2 STYLES","Разговор с начальником":"Parler à son patron","Трудная обратная связь. Неудачный ответ оставляет на месте, удачный пускает дальше и называет приём, на котором он держится.":"Un retour difficile. Une mauvaise réponse te laisse sur place, une bonne te fait avancer et nomme la technique.","Тренажёр разговора":"Entraînement à la conversation","КВЕСТ · 5 ШАГОВ · 2 СТИЛЯ":"QUÊTE · 5 ÉTAPES · 2 STYLES","Сказать «нет» коллеге":"Dire « non » à un collègue","Отказать на просьбу о выходных так, чтобы не поссориться: пауза, спокойное «нет», держать решение, предложить своё.":"Refuser une demande pour le week-end sans conflit : pause, un « non » calme, tenir sa décision, proposer autre chose.","Границы на работе":"Limites au travail","Разговор с мамой о границах":"Parler des limites avec maman","Сохранить близость и право решать самому: признать чувства, сказать «я», договориться о понятном ритме.":"Garder la proximité et le droit de décider : reconnaître les sentiments, parler en « je », convenir d’un rythme clair.","Границы в семье":"Limites en famille","Извиниться и починить":"S’excuser et réparer","Подвели близкого человека. Как извиниться конкретно, выслушать и предложить, что исправите.":"Tu as déçu un proche. Comment t’excuser concrètement, écouter et proposer une réparation.","Конфликт и примирение":"Conflit et réconciliation","Попросить о помощи":"Demander de l’aide","Попросить так, чтобы человеку было легко и согласиться, и отказать: конкретно, без извинений, с взаимностью.":"Demande de façon à ce qu’il soit facile d’accepter ou de refuser : concret, sans s’excuser à l’excès, avec réciprocité.","Просьбы":"Demandes","Разговор о деньгах":"Parler d’argent","Обсудить неравные общие расходы без обвинений: факты, отражение, пропорциональное решение, срок сверки.":"Discuter de dépenses communes inégales sans reproches : faits, reformulation, solution proportionnelle, date de bilan.","Деньги и близкие":"L’argent et les proches","Сказать, что тебе нужно":"Dire ce dont tu as besoin","Попросить больше времени вместе, не обвиняя: мягкий старт, «я»-сообщение, валидация, небольшой эксперимент.":"Demander plus de temps ensemble sans accuser : début doux, message en « je », validation, petite expérience.","Отношения":"Relations","Отказать другу":"Refuser à un ami","Отказаться от поездки так, чтобы дружба не пострадала: пауза, тёплое «нет», повтор решения, альтернатива.":"Refuser un voyage sans abîmer l’amitié : pause, un « non » chaleureux, répéter sa décision, une alternative.","Дружба и границы":"Amitié et limites","Другие сюжетные направления · 12 коротких историй":"Autres histoires · 12 récits courts (en russe)","Границы без ссоры":"Des limites sans dispute","Учиться говорить о своих возможностях и желаниях.":"Apprendre à parler de ses possibilités et de ses envies.","ИГРАТЬ · 2 ДНЯ":"JOUER · 2 JOURS","Тревога и неопределённость":"Anxiété et incertitude","Отличать риск от тревожных предположений.":"Distinguer le risque réel des suppositions anxieuses.","ИГРАТЬ · 4 ГЛАВЫ":"JOUER · 4 CHAPITRES","Внутренний критик":"Le critique intérieur","Находить более честный и бережный внутренний голос.":"Trouver une voix intérieure plus honnête et bienveillante.","Сложный разговор":"Une conversation difficile","Тренировать фразы и слушать ответ собеседника.":"S’entraîner aux phrases et écouter la réponse de l’autre.","Когда нет сил":"Quand on n’a plus d’énergie","Планировать восстановление без гонки продуктивности.":"Planifier la récupération sans course à la productivité.","Свои решения":"Tes propres décisions","Замечать чужие ожидания и выбирать свой шаг.":"Remarquer les attentes des autres et choisir son pas.","Отношения с собой":"La relation avec soi","Собирать опоры, которые не зависят от оценки других.":"Rassembler des appuis qui ne dépendent pas du jugement des autres.","Одиночество и близость":"Solitude et proximité","Искать посильные способы установить контакт.":"Chercher des façons accessibles de créer du lien.","Работа и выгорание":"Travail et épuisement","Замечать нагрузку и договариваться о границах.":"Remarquer la charge et convenir de limites.","Потеря и перемены":"Perte et changements","Давать место чувствам и искать поддержку.":"Laisser de la place aux sentiments et chercher du soutien.","Тело и забота":"Corps et soin","Замечать сигналы тела без оценивания внешности.":"Remarquer les signaux du corps sans juger l’apparence.","Отделять свои потребности от требований других.":"Distinguer ses besoins des exigences des autres.","Первая история — полноценная, на том же движке, что «Тихий город». Остальные одиннадцать — короткие зарисовки на четыре сцены, их предстоит переписать так же.":"La première histoire est complète, sur le même moteur que « Ville tranquille ». Les onze autres sont de courtes esquisses en quatre scènes, à réécrire de la même façon.","Инструменты на каждый день":"Des outils pour chaque jour","Библиотека практик":"Bibliothèque d’exercices","Выбирай то, что подходит моменту. Можно пропустить любой шаг.":"Choisis ce qui convient au moment. Tu peux sauter n’importe quelle étape.","ПРАКТИКА В ФОКУСЕ · 4–6 МИНУТ":"EXERCICE À LA UNE · 4–6 MINUTES","Когда слова ещё звучат в голове. Сначала найдём опору, затем разберём событие и выберем один посильный шаг.":"Quand les mots résonnent encore. D’abord trouver un appui, puis démêler l’événement et choisir un pas réaliste.","01 · Опора":"01 · Ancrage","02 · Ясность":"02 · Clarté","03 · Действие":"03 · Action","Попробовать практику →":"Essayer l’exercice →","Подходит сейчас":"Adapté maintenant","Без сравнения":"Sans comparaison","Заметь мысль «другие справляются лучше». Замени её на конкретный факт о сегодняшней нагрузке.":"Remarque la pensée « les autres s’en sortent mieux ». Remplace-la par un fait concret sur ta charge du jour.","Работа":"Travail","Рабочая граница":"Une limite au travail","Назови реалистичный срок и то, что потребуется, чтобы уложиться. Не обещай невозможного.":"Donne un délai réaliste et ce qu’il faudra pour le tenir. Ne promets pas l’impossible.","Злость":"Colère","Граница одной фразой":"Une limite en une phrase","Попробуй фразу: «Мне важно обсудить задачу, когда мы сможем говорить спокойно». Подстрой её под себя.":"Essaie la phrase : « C’est important pour moi d’en parler quand on pourra discuter calmement. » Adapte-la à toi.","Маршруты: несколько шагов подряд":"Parcours : plusieurs étapes d’affilée","После трудного разговора с начальником":"Après une conversation difficile avec son patron","практика":"exercice","Вернуться в момент":"Revenir au moment présent","Отметить":"Cocher","После критики":"Après une critique","Факты после встречи":"Les faits après la réunion","тренажёр":"entraînement","Ответ начальнику":"Répondre à son patron","Научиться говорить «нет»":"Apprendre à dire « non »","Пауза перед ответом":"Une pause avant de répondre","Право на нет":"Le droit de dire non","Сложный разговор с близким":"Une conversation difficile avec un proche","Сначала услышать":"D’abord écouter","Я-сообщение":"Message en « je »","Близость и границы":"Proximité et limites","Помириться после ссоры":"Se réconcilier après une dispute","Моя часть":"Ma part","Тёплое сообщение":"Un message chaleureux","Когда совсем нет сил":"Quand il n’y a plus aucune énergie","Базовые нужды":"Besoins de base","Минимальный шаг":"Le plus petit pas","Просьба о помощи":"Demander de l’aide","Тихая прогулка":"Une promenade tranquille","Спокойный вечер":"Une soirée calme","Вечерняя граница":"Une limite le soir","Выгрузить мысли":"Vider sa tête","Переход ко сну":"Glisser vers le sommeil","Поиск практики":"Chercher un exercice","Например: тревога, начальник, сон…":"par ex. anxiété, patron, sommeil…","Все":"Tout","Перегрузка":"Surcharge","Сон":"Sommeil","Нет сил":"Plus d’énergie","Мысли":"Pensées","Мягкое дыхание":"Respiration douce","Замедлиться и почувствовать опору.":"Ralentir et sentir un appui.","Переключить внимание на то, что вокруг.":"Porter l’attention sur ce qui t’entoure.","Слова и границы":"Les mots et les limites","Когда чужие слова задели слишком сильно.":"Quand les mots de quelqu’un ont trop blessé.","Разложить по полочкам":"Mettre de l’ordre","Отделить событие от мыслей о нём.":"Séparer l’événement de ce qu’on en pense.","Тёплая фраза":"Une phrase chaleureuse","Поддержать себя без требования быть сильнее.":"Se soutenir sans exiger d’être plus fort.","Смена обстановки":"Changer de cadre","Вода, движение или немного воздуха.":"De l’eau, du mouvement ou un peu d’air.","Три опоры":"Trois appuis","Оглянись и назови три устойчивых предмета рядом. Почувствуй стопы на полу. Сделай один удобный выдох.":"Regarde autour de toi et nomme trois objets stables. Sens tes pieds au sol. Fais une expiration confortable.","Длинный выдох":"Une longue expiration","Вдохни естественно, затем выдохни немного медленнее. Повтори несколько раз без задержки дыхания и без усилия.":"Inspire naturellement, puis expire un peu plus lentement. Répète quelques fois sans bloquer ni forcer.","Проверка фактов":"Vérifier les faits","Запиши: что я знаю точно, что предполагаю и что могу уточнить. Не требуй от себя немедленного решения.":"Note : ce que je sais avec certitude, ce que je suppose et ce que je peux vérifier. N’exige pas de décision immédiate.","План на ближайший час":"Un plan pour l’heure qui vient","Выбери одно безопасное и выполнимое действие на ближайший час. Остальное пока оставь на потом.":"Choisis une action sûre et faisable pour l’heure qui vient. Le reste attendra.","Найди цвет":"Trouve une couleur","Выбери цвет и найди вокруг пять предметов этого цвета. Верни внимание к комнате, когда мысли ускоряются.":"Choisis une couleur et trouve cinq objets de cette couleur autour de toi. Ramène ton attention dans la pièce quand les pensées s’emballent.","Контакт с поверхностью":"Contact avec le support","Заметь, как кресло или пол поддерживают тело. Опиши про себя три точки контакта.":"Remarque comment la chaise ou le sol soutient ton corps. Décris intérieurement trois points de contact.","Язык":"Langue","Язык интерфейса, практик и разговора. Квесты и сюжетные игры пока на русском.":"Langue de l’interface, des exercices et de la conversation. Les quêtes et jeux narratifs sont en russe pour l’instant.","Только то, что рассказано тобой":"Seulement ce que tu as partagé","Что обо мне известно":"Ce qu’on sait de moi","Чтобы «Рядом» мог подсказать, куда сходить, что поесть и что поможет, ему нужно знать тебя. Здесь видно всё, что он помнит. Записи остаются только на этом устройстве: любую можно удалить.":"Pour que Ryadom suggère où aller, quoi manger et ce qui aidera, il doit te connaître. Tout ce qu’il retient est visible ici. Les entrées restent uniquement sur cet appareil, et chacune peut être supprimée.","Использовать в разговоре и подсказках":"Utiliser dans la conversation et les idées","Подтянуть из любимых мест":"Importer depuis les lieux favoris","Что люблю есть":"Ce que j’aime manger","блюда, кухня, вкусы":"plats, cuisine, goûts","например: тёплый суп, кофе с булочкой":"par ex. soupe chaude, café et brioche","Где мне хорошо":"Où je me sens bien","места и обстановка":"lieux et ambiance","например: набережная, тихая библиотека":"par ex. les quais, une bibliothèque calme","Как люблю проводить время":"Comment j’aime passer le temps","занятия и ритм":"activités et rythme","например: долгая прогулка, кино вечером":"par ex. une longue marche, un film le soir","Что помогает, когда тяжело":"Ce qui aide quand c’est dur","то, что правда работает":"ce qui marche vraiment","например: горячий чай, музыка в наушниках":"par ex. thé chaud, musique au casque","С кем мне легко":"Avec qui je suis à l’aise","люди и формат общения":"personnes et façons d’être ensemble","например: с сестрой, один на один":"par ex. avec ma sœur, en tête-à-tête","Чего лучше избегать":"Ce qu’il vaut mieux éviter","что выматывает или раздражает":"ce qui épuise ou agace","например: шумные места, спешка":"par ex. lieux bruyants, précipitation","Стереть всё, что обо мне записано":"Effacer tout ce qui est enregistré sur moi","Дневник, места и игровой прогресс — отдельные данные: их очистка здесь не затрагивается.":"Le journal, les lieux et la progression des jeux sont des données séparées : les effacer ici ne les touche pas.","Моя активность за 7 дней":"Mon activité sur 7 jours","Считается только на этом устройстве и никуда не отправляется. Помогает понять, чем ты пользуешься.":"Compté uniquement sur cet appareil, jamais envoyé. Aide à voir ce que tu utilises.","Пока нет данных.":"Pas encore de données.","Скопировать сводку":"Copier le résumé","Сбросить счётчики":"Réinitialiser les compteurs","Данные и конфиденциальность":"Données et confidentialité","Всё, что ты вводишь, остаётся на этом устройстве. Здесь можно посмотреть, что хранится, сохранить копию или удалить всё.":"Tout ce que tu saisis reste sur cet appareil. Ici tu peux voir ce qui est stocké, en faire une copie ou tout supprimer.","Другие данные приложения":"Autres données de l’appli","Сохранить копию файлом":"Enregistrer une copie dans un fichier","Скопировать текст":"Copier le texte","Восстановить из файла":"Restaurer depuis un fichier","Файл с данными":"Fichier de données","Восстановить из вставленного текста":"Restaurer depuis le texte collé","Удалить все мои данные":"Supprimer toutes mes données","Как приложение обращается с данными":"Comment l’appli traite les données","Где хранятся.":"Où c’est stocké.","В памяти браузера или приложения на этом устройстве. Учётных записей и серверной базы нет. Если очистить данные браузера или сменить устройство без копии, записи пропадут.":"Dans la mémoire du navigateur ou de l’appli sur cet appareil. Pas de compte ni de base sur un serveur. Si tu effaces les données du navigateur ou changes d’appareil sans copie, les entrées seront perdues.","Что передаётся наружу.":"Ce qui est envoyé à l’extérieur.","Поиск мест: текст запроса и, если разрешишь, примерные координаты уходят в сервисы карт OpenStreetMap (Photon, Nominatim). Режим с сервером и ИИ, если он подключён: текст твоих сообщений уходит на сервер и к ИИ-провайдеру, чтобы получить ответ. Голосовой ввод и озвучка используют службы устройства.":"Recherche de lieux : le texte de la recherche et, si tu l’autorises, la position approximative vont aux services cartographiques d’OpenStreetMap (Photon, Nominatim). Mode serveur et IA, s’il est activé : le texte de tes messages va au serveur et au fournisseur d’IA pour obtenir une réponse. La saisie et la lecture vocales utilisent les services de l’appareil.","Что приложение не делает.":"Ce que l’appli ne fait pas.","Не следит за перемещениями, не продаёт и не показывает рекламу, не ставит диагнозов. Счётчики использования считаются только на этом устройстве.":"Elle ne suit pas tes déplacements, ne vend rien, n’affiche pas de publicité et ne pose pas de diagnostic. Les compteurs d’usage restent sur cet appareil.","Важно.":"Important.","Приложение не является медицинским изделием и не заменяет помощь специалиста. Это прототип, и тексты ещё не проверены психологом.":"L’appli n’est pas un dispositif médical et ne remplace pas l’aide d’un professionnel. C’est un prototype ; les textes n’ont pas encore été relus par un psychologue.","Показать вводную ещё раз":"Revoir l’introduction","Если сейчас очень тяжело или есть риск навредить себе, позвони по номеру 112 или обратись к близкому человеку.":"Si c’est très dur maintenant ou s’il y a un risque de te faire du mal, appelle le 112 ou tourne-toi vers un proche.","Дневник":"Journal","Закрыть":"Fermer","Маленький шаг":"Un petit pas","Практика после трудного разговора":"Exercice après une conversation difficile","Прежде чем начать":"Avant de commencer","Коротко о том, как устроено «Рядом».":"En bref, comment fonctionne Ryadom.","Что это":"Ce que c’est","Цифровой помощник для разговора о состоянии, тренировки трудных разговоров и подбора мест. Это не врач и не психолог, диагнозов не ставит и не заменяет специалиста.":"Un assistant numérique pour parler de ton état, t’entraîner aux conversations difficiles et trouver des lieux. Ce n’est ni un médecin ni un psychologue : il ne pose pas de diagnostic et ne remplace pas un professionnel.","Где данные":"Où sont les données","Дневник, разговоры и «Обо мне» хранятся только на этом устройстве. Ты можешь выгрузить их или удалить всё в разделе «Обо мне».":"Le journal, les conversations et « À propos de moi » restent uniquement sur cet appareil. Tu peux les exporter ou tout supprimer dans « À propos de moi ».","Что уходит наружу":"Ce qui est envoyé à l’extérieur","Поиск мест отправляет запрос карте (OpenStreetMap). Если подключён режим с сервером и ИИ, текст сообщения уходит на сервер для ответа. Голосовой ввод использует службы твоего устройства.":"La recherche de lieux envoie ta requête à un service de cartes (OpenStreetMap). Si le mode serveur et IA est activé, le texte du message part au serveur pour la réponse. La saisie vocale utilise les services de ton appareil.","Если тяжело всерьёз":"Si c’est vraiment dur","При мыслях о вреде себе или другим обратись к человеку рядом или по номеру 112. Приложение подскажет, но срочную помощь оно не заменит.":"Si tu as des pensées de te faire du mal ou d’en faire à d’autres, tourne-toi vers quelqu’un de proche ou appelle le numéro d’urgence (112 dans de nombreux pays). L’appli peut orienter, mais ne remplace pas une aide urgente.","Понятно, продолжить":"Compris, continuer","Рядом — маленькие шаги к себе":"Ryadom — de petits pas vers soi","Тревожно":"Anxieux","Сегодняшняя отметка сохранена. Её можно изменить.":"Le relevé du jour est enregistré. Tu peux le modifier.","дней с отметкой 3–4 из 4":"jours notés 3–4 sur 4","Добавить в любимые":"Ajouter aux favoris","Любимое место":"Lieu favori","Изменить":"Modifier","Удалить":"Supprimer","Разговоры за этот день":"Conversations de ce jour","Удалить разговоры за этот день":"Supprimer les conversations de ce jour","Из «Обо мне»:":"D’après « À propos de moi » :","добавлено мной":"ajouté par moi","из разговора":"de la conversation","Отметки состояния":"Relevés d’état","Отметка о вводном экране":"Écran d’introduction vu","Разговоры":"Conversations","Дневник настроения":"Journal d’humeur","Посещённые места":"Lieux visités","Профиль «Обо мне»":"Profil « À propos de moi »","Меньше новостей":"Moins d’actualités","Если поток новостей усиливает тревогу, отложи его на 15 минут и выбери конкретное время для проверки.":"Si le fil d’actualités augmente l’anxiété, mets-le de côté 15 minutes et choisis un moment précis pour le consulter.","Кому можно написать":"À qui écrire","Выбери человека, которому можно коротко написать: «Мне тревожно. Можешь побыть на связи?»":"Choisis une personne à qui écrire brièvement : « Je suis anxieux·se. Tu peux rester joignable un moment ? »","Назвать чувство":"Nommer le sentiment","Скажи себе: «Мне сейчас грустно». Не объясняй и не исправляй это чувство в ту же секунду.":"Dis-toi : « Je suis triste en ce moment. » N’explique pas et ne corrige pas tout de suite ce sentiment.","Мягкий день":"Une journée douce","Составь минимальный план: еда, вода, один обязательный шаг и один посильный источник тепла.":"Fais un plan minimal : manger, boire, une étape indispensable et une source de chaleur accessible.","Память о хорошем":"Se souvenir du bon","Вспомни один спокойный момент за последнюю неделю. Запиши детали: место, свет, звук.":"Rappelle-toi un moment calme de la semaine passée. Note les détails : lieu, lumière, son.","Тёплый контакт":"Un contact chaleureux","Напиши близкому человеку одну честную фразу о своём состоянии, если хочется быть услышанной или услышанным.":"Écris à un proche une phrase honnête sur ton état, si tu as envie d’être entendu·e.","Разрешить паузу":"S’autoriser une pause","Поставь таймер на пять минут. Можно просто посидеть, не превращая отдых в задачу.":"Mets un minuteur de cinq minutes. Tu peux juste t’asseoir, sans faire du repos une tâche.","Небольшая забота":"Un petit soin","Выбери одну бережную вещь: плед, душ, чай или прогулку. Отметь, стало ли хоть немного легче.":"Choisis une chose douce : un plaid, une douche, un thé ou une promenade. Note si c’est devenu un peu plus facile.","Свет и воздух":"Lumière et air","Если удобно, подойди к окну или выйди на несколько минут. Заметь температуру воздуха и положение тела.":"Si possible, approche-toi de la fenêtre ou sors quelques minutes. Remarque la température de l’air et la position de ton corps.","Прежде чем отвечать, отойди от переписки на пару минут. Спроси себя, какой результат нужен от ответа.":"Avant de répondre, éloigne-toi de la conversation quelques minutes. Demande-toi quel résultat tu attends de ta réponse.","Где злость в теле":"Où est la colère dans le corps","Заметь, где в теле сейчас напряжение. Расслабь челюсть или плечи, если это приятно, не подавляя чувство.":"Remarque où se trouve la tension dans ton corps. Relâche la mâchoire ou les épaules si c’est agréable, sans étouffer le sentiment.","Черновик без отправки":"Un brouillon jamais envoyé","Напиши резкий ответ в заметке, которую не отправишь. Затем выдели одну просьбу, которую действительно хочешь донести.":"Écris la réponse cinglante dans une note que tu n’enverras pas. Puis isole la seule demande que tu veux vraiment faire passer.","Отойти от экрана":"S’éloigner de l’écran","Положи телефон и сделай несколько шагов. Возвращайся к разговору, когда сможешь выбрать тон.":"Pose ton téléphone et fais quelques pas. Reviens à la conversation quand tu pourras choisir ton ton.","Что задело":"Ce qui a blessé","Раздели на две строки: что произошло и какую важную потребность это затронуло.":"Sépare en deux lignes : ce qui s’est passé et quel besoin important cela a touché.","Безопасная разрядка":"Décharge sans risque","Сильно прижми стопы к полу на несколько секунд, затем отпусти. Повтори комфортно, без боли.":"Appuie fort tes pieds au sol quelques secondes, puis relâche. Répète confortablement, sans douleur.","Право отложить":"Le droit de remettre à plus tard","Если нет срочности, назначь время ответа позже. Тебе не обязательно решать конфликт в пике эмоций.":"Si ce n’est pas urgent, fixe un moment pour répondre plus tard. Tu n’es pas obligé·e de régler un conflit au pic de l’émotion.","Одна задача":"Une seule tâche","Выпиши всё, что давит. Обведи одну задачу, которую можно начать за десять минут.":"Note tout ce qui pèse. Entoure une tâche que tu peux commencer en dix minutes.","Пять процентов":"Cinq pour cent","Спроси: что сделает ближайший час на пять процентов легче? Выбери один маленький шаг.":"Demande-toi : qu’est-ce qui rendrait l’heure qui vient cinq pour cent plus facile ? Choisis un petit pas.","Снять лишнее":"Enlever le superflu","Посмотри на список дел и вычеркни, перенеси или попроси помощи хотя бы с одним пунктом.":"Regarde ta liste de tâches : barre, reporte ou demande de l’aide pour au moins un point.","Перерыв между делами":"Une pause entre deux tâches","Перед новой задачей сделай паузу: вода, взгляд вдаль, несколько спокойных движений.":"Avant une nouvelle tâche, fais une pause : de l’eau, un regard au loin, quelques mouvements calmes.","Проверка тела":"Faire le point sur le corps","Заметь голод, жажду, усталость и напряжение. Начни с самой простой телесной потребности.":"Remarque la faim, la soif, la fatigue et la tension. Commence par le besoin le plus simple.","Достаточно на сегодня":"Assez pour aujourd’hui","Сформулируй критерий «достаточно хорошо» для одной задачи. Остановись, когда он достигнут.":"Définis le « suffisamment bien » pour une tâche. Arrête-toi quand tu l’atteins.","Попросить ясности":"Demander de la clarté","Если запрос размытый, уточни срок, приоритет и ожидаемый результат у того, кто его дал.":"Si une demande est floue, précise le délai, la priorité et le résultat attendu auprès de la personne qui l’a faite.","Тихое окно":"Une fenêtre au calme","На десять минут отключи необязательные уведомления и займись одним делом.":"Pendant dix minutes, coupe les notifications non essentielles et fais une seule chose.","За некоторое время до сна снизь яркость экрана и выбери спокойное занятие без цели «уснуть немедленно».":"Un moment avant de dormir, baisse la luminosité de l’écran et choisis une activité calme, sans objectif de « m’endormir tout de suite ».","Запиши незавершённые дела и один следующий шаг к каждому. Вернуться к списку можно завтра.":"Note les tâches inachevées et une prochaine étape pour chacune. Tu pourras revenir à la liste demain.","Комфортная поза":"Une position confortable","Устрой тело удобнее и мягко замечай точки опоры. Дыхание оставь естественным.":"Installe ton corps plus confortablement et remarque doucement les points d’appui. Laisse la respiration naturelle.","Тихие звуки":"Sons discrets","Прислушайся к трём звукам вокруг. Не оценивай их, просто отмечай появление и исчезновение.":"Écoute trois sons autour de toi. Ne les juge pas, remarque seulement leur apparition et leur disparition.","Без борьбы со сном":"Sans lutter contre le sommeil","Если не спится, напомни себе: отдых тоже ценен. Выбери спокойное занятие и вернись в постель, когда захочется.":"Si tu n’arrives pas à dormir, rappelle-toi que le repos compte aussi. Choisis une activité calme et retourne au lit quand tu en as envie.","Назначь момент, после которого рабочие сообщения подождут до завтра, если это возможно.":"Fixe un moment après lequel les messages pro attendront demain, si c’est possible.","Мягкое завершение":"Une fin en douceur","Назови одну вещь, которую удалось сделать сегодня. Даже очень маленькую.":"Nomme une chose que tu as réussi à faire aujourd’hui. Même toute petite.","Спокойное утро":"Un matin calme","Подготовь одну мелочь для утра: одежду, стакан воды или список первого дела.":"Prépare une petite chose pour le matin : des vêtements, un verre d’eau ou la première tâche notée.","Составь фразу: «Когда произошло…, мне было… Мне хотелось бы…».":"Construis une phrase : « Quand … s’est passé, je me suis senti·e … J’aimerais … ».","Перескажи своими словами, что было услышано от другого человека, и уточни, верно ли это понято.":"Reformule avec tes mots ce que tu as entendu de l’autre, et vérifie si tu as bien compris.","Попробуй короткий ответ без длинного оправдания: «Сейчас я не могу. Давай обсудим другой вариант».":"Essaie une réponse courte sans longue justification : « Là, je ne peux pas. Voyons une autre option. »","Раздели лист: «за что отвечаю я» и «за что отвечает другой». Не бери на себя обе стороны.":"Partage une feuille : « ce dont je suis responsable » et « ce dont l’autre est responsable ». Ne prends pas les deux côtés.","Пауза в разговоре":"Une pause dans la conversation","Если разговор накаляется, предложи вернуться к нему в конкретное время после паузы.":"Si la conversation s’échauffe, propose d’y revenir à un moment précis après une pause.","Запиши: как я хочу поддерживать контакт и что мне при этом важно решать самостоятельно.":"Note : comment je veux garder le lien et ce que je tiens à décider moi-même.","Один вопрос":"Une seule question","Вместо догадки спроси: «Что именно ты имеешь в виду?» Дай другому возможность прояснить слова.":"Au lieu de deviner, demande : « Que veux-tu dire exactement ? » Laisse à l’autre la possibilité de préciser.","Если хочется контакта, отправь простое сообщение без ожидания немедленного ответа.":"Si tu as envie de contact, envoie un message simple sans attendre de réponse immédiate.","После сложного разговора запиши конкретные задачи и договорённости отдельно от тона и эмоций.":"Après une conversation difficile, note les tâches et accords concrets séparément du ton et des émotions.","Уточнить приоритет":"Préciser la priorité","Спроси, какое из двух дел важнее сегодня. Это превращает неопределённость в выбор.":"Demande laquelle des deux tâches compte le plus aujourd’hui. L’incertitude devient un choix.","Составь спокойный черновик: факт, уточняющий вопрос и срок, когда вернёшься с ответом.":"Écris un brouillon calme : le fait, une question pour préciser et quand tu reviendras avec une réponse.","Раздели обратную связь на полезную часть, спорную часть и форму подачи. Возьми только то, что поможет задаче.":"Sépare le retour en partie utile, partie discutable et forme. Ne garde que ce qui aide la tâche.","Маленькая победа":"Une petite victoire","Запиши одно завершённое дело за день. Даже если другие ещё ждут.":"Note une tâche terminée aujourd’hui. Même si d’autres attendent encore.","Переход домой":"Passer en mode maison","Закрой рабочий день короткой заметкой о первом шаге на завтра. Переключись на другую деятельность.":"Clôture la journée de travail par une courte note sur le premier pas de demain. Passe à autre chose.","Найти союзника":"Trouver un allié","Подумай, кто может помочь уточнить задачу, дать контекст или поддержать после трудного разговора.":"Pense à qui pourrait aider à préciser la tâche, donner du contexte ou te soutenir après une conversation difficile.","Вернуться к опоре, отделить событие от мыслей и выбрать свой следующий шаг.":"Revenir à un appui, séparer l’événement des pensées et choisir son prochain pas.","Проверь сон, еду, воду и паузы. Выбери самое доступное сейчас.":"Vérifie sommeil, repas, eau et pauses. Choisis ce qui est le plus accessible maintenant.","Сократи задачу до действия на две минуты. Можно остановиться после него.":"Réduis la tâche à une action de deux minutes. Tu peux t’arrêter après.","Не объяснять усталость":"Ne pas justifier la fatigue","Скажи себе: «Сил мало, и я могу выбрать посильный темп». Определи один обязательный пункт.":"Dis-toi : « J’ai peu d’énergie et je peux choisir un rythme tenable. » Identifie un seul point obligatoire.","Пауза без экрана":"Une pause sans écran","На несколько минут убери экран и посмотри вдаль или закрой глаза, если комфортно.":"Pendant quelques minutes, éloigne l’écran et regarde au loin, ou ferme les yeux si c’est confortable.","Сформулируй конкретную небольшую просьбу человеку, который может помочь.":"Formule une petite demande précise à quelqu’un qui peut aider.","Список «потом»":"Une liste « plus tard »","Запиши необязательные дела в список на другой день, чтобы не держать их в голове.":"Note les tâches non essentielles sur une liste pour un autre jour, pour ne pas les garder en tête.","Если есть силы и безопасно, пройди несколько минут в удобном темпе. Отдых тоже остаётся вариантом.":"Si tu en as la force et que c’est sûr, marche quelques minutes à un rythme confortable. Se reposer reste aussi une option.","Один приятный момент":"Un moment agréable","Выбери простую вещь, которая не требует подготовки: музыка, вода, окно или тёплый душ.":"Choisis une chose simple, sans préparation : musique, eau, fenêtre ou douche chaude.","Мысль или факт":"Pensée ou fait","Запиши тревожную мысль и рядом — факты за и против. Оставь место для неизвестного.":"Écris la pensée anxieuse et, à côté, les faits pour et contre. Laisse de la place à l’inconnu.","Название мысли":"Nommer la pensée","Когда мысль повторяется, произнеси: «У меня появилась мысль, что…». Это создаёт небольшую дистанцию.":"Quand une pensée revient, dis : « J’ai la pensée que… ». Cela crée un peu de distance.","Круг влияния":"Cercle d’influence","Раздели ситуацию на то, что можешь изменить, на что можешь повлиять и что сейчас вне контроля.":"Sépare la situation en ce que tu peux changer, ce sur quoi tu peux influer et ce qui t’échappe pour l’instant.","Один следующий шаг":"Un seul pas suivant","Вместо полного плана выбери действие, которое можно сделать сегодня.":"Au lieu d’un plan complet, choisis une action faisable aujourd’hui.","Вернуться к ощущениям":"Revenir aux sensations","Назови три звука, две видимые детали и одно ощущение от поверхности под рукой.":"Nomme trois sons, deux détails visibles et une sensation de la surface sous ta main.","Время для мысли":"Un moment pour la pensée","Если мысль возвращается, запиши её и назначь короткое время позже, когда сможешь к ней вернуться.":"Si la pensée revient, note-la et fixe un court moment plus tard pour y revenir.","Два объяснения":"Deux explications","Найди ещё одно возможное объяснение событию, кроме самого пугающего. Не обязательно верить в него сразу.":"Trouve une autre explication possible, en plus de la plus effrayante. Pas besoin d’y croire tout de suite.","Спросить, а не угадать":"Demander plutôt que deviner","Если мысль касается намерений другого, сформулируй вопрос, который поможет прояснить ситуацию.":"Si la pensée concerne les intentions de quelqu’un, formule une question qui aiderait à clarifier.","Что уже помогает":"Ce qui aide déjà","Заметь, что сейчас поддерживает тебя: человек, место, движение или привычка. Сохрани это в памяти.":"Remarque ce qui te soutient maintenant : une personne, un lieu, le mouvement ou une habitude. Garde-le en mémoire.","Поблагодарить себя":"Se remercier","Назови один свой шаг сегодня без оценки его масштаба.":"Nomme un pas que tu as fait aujourd’hui, sans juger de son ampleur.","Фото момента":"Une photo du moment","Опиши словами спокойный момент: цвет, звук, температуру и чувство в теле.":"Décris un moment calme avec des mots : couleur, son, température et sensation dans le corps.","Забота на завтра":"Prendre soin de demain","Выбери одну маленькую вещь, которую хочется повторить завтра.":"Choisis une petite chose que tu aimerais refaire demain.","Делиться хорошим":"Partager le positif","Если хочется, расскажи кому-то о приятном моменте, не превращая это в отчёт.":"Si tu en as envie, raconte à quelqu’un un moment agréable, sans en faire un compte rendu.","Просто побыть":"Juste être là","Разреши себе несколько минут ничего не улучшать. Замечай, что уже есть.":"Accorde-toi quelques minutes sans rien améliorer. Remarque ce qui est déjà là.","Мягкий план":"Un plan en douceur","Пока спокойно, запиши, что обычно помогает в более сложные дни.":"Pendant que tu es calme, note ce qui t’aide d’habitude les jours plus durs.","Свободное время":"Temps libre","Оставь в дне небольшой отрезок без обязательного результата.":"Garde dans la journée un petit moment sans résultat obligatoire.","2 минуты":"2 minutes","Дыши комфортно, без задержки и усилия. На вдохе круг расширяется, на выдохе сужается. Если кружится голова, остановись и дыши обычно.":"Respire confortablement, sans bloquer ni forcer. À l’inspiration le cercle s’agrandit, à l’expiration il rétrécit. Si la tête tourne, arrête-toi et respire normalement.","Начать дыхание":"Commencer la respiration","Закончить":"Terminer","Дыши в своём ритме":"Respire à ton rythme","1 минута":"1 minute","Назови 5 вещей, которые видишь; 4, которые ощущаешь телом; 3 звука. Не спеши. Сейчас ты здесь.":"Nomme 5 choses que tu vois, 4 que tu sens avec ton corps, 3 sons. Sans te presser. Maintenant, tu es ici.","Представь между собой и резкими словами прозрачное стекло. Слова остаются по ту сторону. Спроси себя: что из сказанного относится к задаче, а что говорит о состоянии другого человека?":"Imagine une vitre transparente entre toi et les mots durs. Les mots restent de l’autre côté. Demande-toi : qu’est-ce qui concerne la tâche, et qu’est-ce qui parle plutôt de l’état de l’autre ?","3 минуты":"3 minutes","Запиши три короткие строки: 1) Что произошло? 2) Что я сейчас чувствую? 3) Какой один небольшой шаг мне доступен? Не нужно искать идеальное решение.":"Écris trois lignes courtes : 1) Que s’est-il passé ? 2) Qu’est-ce que je ressens maintenant ? 3) Quel petit pas m’est accessible ? Pas besoin de solution parfaite.","Если бы близкий человек оказался на твоём месте, какие слова поддержки нашлись бы для него? Попробуй обратиться с этой же фразой к себе.":"Si un proche était à ta place, quels mots de soutien trouverais-tu pour lui ? Essaie de te les dire à toi-même.","Если есть возможность, встань, сделай несколько спокойных шагов и выпей воды. Посмотри в окно или выйди на воздух. Потом проверь, изменилось ли что-то хотя бы на один процент.":"Si possible, lève-toi, fais quelques pas calmes et bois de l’eau. Regarde par la fenêtre ou sors prendre l’air. Puis vérifie si quelque chose a changé, même d’un pour cent.","1 мин":"1 min","2 мин":"2 min","3 мин":"3 min","5 мин":"5 min","10 мин":"10 min","✦ РЯДОМ · ПРАКТИКА":"✦ RYADOM · EXERCICE","ПЕРЕД НАЧАЛОМ":"AVANT DE COMMENCER","Что осталось после разговора?":"Que reste-t-il après la conversation ?","Нам не нужно сейчас разбирать всё сразу. Отметь, с кем был разговор и насколько сильно он задел тебя в данный момент.":"Pas besoin de tout démêler maintenant. Indique avec qui était la conversation et à quel point elle t’a touché·e en ce moment.","На работе":"Au travail","С близким":"Avec un proche","В другой ситуации":"Dans une autre situation","Насколько сильно задело сейчас?":"À quel point ça te touche maintenant ?","Немного":"Un peu","Очень сильно":"Très fort","Если сейчас небезопасно или ситуация продолжается, сначала позаботься о своей безопасности и обратись к человеку рядом. Практику можно закрыть в любой момент.":"Si tu n’es pas en sécurité ou si la situation continue, occupe-toi d’abord de ta sécurité et tourne-toi vers quelqu’un de proche. Tu peux fermer l’exercice à tout moment.","Начать →":"Commencer →","01 · ВЕРНУТЬСЯ В МОМЕНТ":"01 · REVENIR AU MOMENT","Сейчас ты здесь":"Maintenant, tu es ici","Не нужно менять дыхание. Найди глазами одну вещь вокруг, услышь один звук и почувствуй опору под ногами или телом. Нажми на то, что удалось заметить.":"Pas besoin de changer ta respiration. Trouve du regard une chose autour de toi, écoute un son et sens l’appui sous tes pieds ou ton corps. Touche ce que tu as remarqué.","здесь":"ici","и сейчас":"et maintenant","○ Вижу предмет":"○ Je vois un objet","○ Слышу звук":"○ J’entends un son","○ Чувствую опору":"○ Je sens un appui","Можно просто прочитать и двигаться дальше. Если внимание к телу неприятно, пропусти этот шаг.":"Tu peux juste lire et continuer. Si l’attention au corps est désagréable, passe cette étape.","Назад":"Retour","Продолжить →":"Continuer →","✓ Вижу предмет":"✓ Je vois un objet","✓ Слышу звук":"✓ J’entends un son","✓ Чувствую опору":"✓ Je sens un appui","02 · ОТДЕЛИТЬ СОБЫТИЕ ОТ МЫСЛИ":"02 · SÉPARER L’ÉVÉNEMENT DE LA PENSÉE","Две разные вещи":"Deux choses différentes","Попробуй разделить то, что произошло, и то, что подумалось после. Это не проверка правильности твоих чувств. Поля можно оставить пустыми.":"Essaie de séparer ce qui s’est passé de ce que tu as pensé après. Ce n’est pas un test de la justesse de tes sentiments. Les champs peuvent rester vides.","Что было сказано или сделано?":"Qu’est-ce qui a été dit ou fait ?","Какая мысль у меня об этом появилась?":"Quelle pensée m’est venue ?","Чувства реальны. Мысль о себе — не всегда факт. Необязательно находить объяснение прямо сейчас.":"Les sentiments sont réels. Une pensée sur soi n’est pas toujours un fait. Pas besoin de trouver une explication tout de suite.","03 · ОДИН СЛЕДУЮЩИЙ ШАГ":"03 · UN SEUL PAS SUIVANT","Что сейчас подойдёт?":"Qu’est-ce qui conviendrait maintenant ?","Выбери действие, которое зависит от тебя. Оно может быть маленьким и не обязано решать весь конфликт.":"Choisis une action qui dépend de toi. Elle peut être petite et n’a pas à résoudre tout le conflit.","Дать себе паузу":"S’accorder une pause","Можно ничего не отправлять прямо сейчас. Назначь момент, когда снова посмотришь на ситуацию.":"Tu n’as rien à envoyer maintenant. Fixe un moment pour regarder à nouveau la situation.","Уточнить задачу":"Préciser la tâche","Этот вариант подходит, если за неприятным тоном была конкретная рабочая задача.":"Cette option convient si derrière le ton désagréable il y avait une tâche précise.","Обозначить границу":"Poser une limite","Подстрой слова под себя. Ты выбираешь время и безопасный способ разговора.":"Adapte les mots à toi. Tu choisis le moment et une façon sûre de parler.","Попросить поддержки":"Demander du soutien","Поддержка может быть короткой: сообщение, звонок или совместная прогулка.":"Le soutien peut être bref : un message, un appel ou une promenade ensemble.","Как сейчас, по той же шкале?":"Et maintenant, sur la même échelle ?","Не хочу оценивать":"Je ne veux pas noter","Завершить и сохранить →":"Terminer et enregistrer →","ВОЗМОЖНАЯ ФРАЗА":"UNE PHRASE POSSIBLE","«Я вернусь к разговору позже. Сейчас мне нужно немного времени».":"« Je reviendrai à cette conversation plus tard. Là, j’ai besoin d’un peu de temps. »","Готово":"Terminé","ТВОЙ МАЛЕНЬКИЙ ШАГ":"TON PETIT PAS","Можно остановиться здесь":"Tu peux t’arrêter ici","Состояние замечено, действие выбрано. Не нужно заставлять себя чувствовать лучше.":"L’état a été remarqué, l’action choisie. Pas besoin de te forcer à aller mieux.","ЧТО ВЫБРАНО":"CE QUI A ÉTÉ CHOISI","Состояние пока не изменилось. Ты всё равно можешь остановиться или выбрать поддержку.":"L’état n’a pas encore changé. Tu peux quand même t’arrêter ou choisir du soutien.","В дневник сохранены только тема, выбранный шаг и твоя оценка результата. Написанные тобой фразы не сохранялись.":"Seuls le thème, le pas choisi et ton évaluation ont été enregistrés dans le journal. Les phrases écrites n’ont pas été gardées.","Вернуться в приложение":"Revenir à l’appli","Добавить место":"Ajouter un lieu","Название *":"Nom *","Например, любимая кофейня":"par ex. ton café préféré","Район или адрес":"Quartier ou adresse","Необязательно":"Facultatif","Примерное время":"Heure approximative","Что это за место?":"Quel genre de lieu ?","Кафе":"Café","Парк":"Parc","Прогулка":"Promenade","Культура":"Culture","Другое":"Autre","Как тебе там было?":"Comment c’était là-bas ?","Спокойно":"Calme","Радостно":"Joyeux","Уютно":"Douillet","Грустно":"Triste","По-разному":"Mitigé","Что запомнилось?":"Qu’est-ce qui t’a marqué ?","Отмена":"Annuler","Сохранить место":"Enregistrer le lieu","Удалить разговоры, отметки, места и любимые места из дневника на этом устройстве? Игровой прогресс останется.":"Supprimer conversations, relevés, lieux et favoris du journal sur cet appareil ? La progression des jeux restera.","{x}: {0}":"{x} : {0}","Сообщений в разговоре":"Messages dans la conversation","Практик открыто":"Exercices ouverts","Тренажёров начато":"Entraînements commencés","Тренажёров пройдено":"Entraînements terminés","Открытий «Практик»":"Ouvertures d’Exercices","Открытий «Игр»":"Ouvertures de Jeux","Открытий «Мест»":"Ouvertures de Lieux","Открытий дневника":"Ouvertures du journal","{x}: {y} {0} из {1}":"{x} : {y} {0} sur {1}","тревога":"anxiété","грусть":"tristesse","беспокойство":"agitation","спокойствие":"calme","Да, удалить":"Oui, supprimer","Неспешная прогулка, книга или чашка чая. Выбирай только то, на что есть силы.":"Une balade tranquille, un livre ou une tasse de thé. Choisis seulement ce pour quoi tu as de l’énergie.","Место, где можно сменить обстановку. Тишину и отсутствие людей лучше проверить самому.":"Un lieu pour changer d’air. Vérifie toi-même le calme et l’affluence.","Прогулка, вид на город или уютное место для встречи.":"Une balade, une vue sur la ville ou un endroit cosy pour se retrouver.","Места, где можно гулять, смотреть кино или быть среди людей.":"Des lieux pour se promener, voir un film ou être parmi les gens.","Пространства для неторопливого времени.":"Des espaces pour prendre son temps.","Музей, галерея или книжное место могут дать новую мысль.":"Un musée, une galerie ou une librairie peuvent apporter une idée neuve.","Поблизости и без большого плана: кофе или короткая прогулка.":"À proximité et sans grand plan : un café ou une courte balade.","Места для встречи. Загруженность и атмосферу уточни перед поездкой.":"Des lieux de rencontre. Vérifie l’affluence et l’ambiance avant d’y aller.","Будут удалены дневник, разговоры, «Обо мне», места и прогресс игр на этом устройстве. Вернуть их будет нельзя, если нет копии.":"Le journal, les conversations, « À propos de moi », les lieux et la progression des jeux sur cet appareil seront supprimés. Impossible de les récupérer sans copie.","Да, удалить всё":"Oui, tout supprimer","Удалить все записи профиля? Вернуть их будет нельзя.":"Supprimer toutes les entrées du profil ? Impossible de les récupérer.","Да, стереть":"Oui, effacer","После нескольких отметок здесь появится короткое наблюдение о твоём состоянии.":"Après quelques relevés, une courte observation sur ton état apparaîtra ici.","Здесь появятся твои отметки после первого разговора.":"Tes relevés apparaîtront ici après la première conversation.","Разговор с «Рядом»":"Conversation avec Ryadom","Например: трудный разговор, прогулка или приятный момент":"Par exemple : une conversation difficile, une balade ou un bon moment","Интерактивный прототип приложения ежедневной эмоциональной поддержки.":"Prototype interactif d’une application de soutien émotionnel au quotidien.","Твои мысли остаются только на этом экране и не сохраняются":"Tes pensées restent uniquement sur cet écran et ne sont pas enregistrées","Заметка":"Note","Как ты сейчас после этого шага?":"Comment te sens-tu après cette étape ?","Чуть легче":"Un peu plus léger","Пока так же":"Pareil pour l’instant","Стало хуже":"C’est pire","День":"Jour","Отмечено состояний: {0}. График показывает только твои ответы, без оценок и диагнозов.":"États notés : {0}. Le graphique montre seulement tes réponses, sans jugement ni diagnostic.","Одна короткая отметка в день — уже начало.":"Un court relevé par jour, c’est déjà un début.","Удалить все отметки из этого браузера?":"Supprimer tous les relevés de ce navigateur ?","В {0} из {1} отмеченных дней тревога была сильной. Можно посмотреть, что происходило в эти дни, и обратиться за поддержкой, если это мешает жить.":"Sur {0} des {1} jours notés, l’anxiété était forte. Tu peux regarder ce qui se passait ces jours-là et chercher du soutien si cela gêne ta vie.","За выбранный период сильная тревога отмечалась в {0} из {1} дней. Посмотри, какие занятия и разговоры помогали тебе чувствовать себя спокойнее.":"Sur la période choisie, une forte anxiété a été notée {0} jours sur {1}. Regarde quelles activités et conversations t’ont aidé·e à te sentir plus calme.","На этот день нет записи. Пустая клетка ничего не говорит о том, каким был день.":"Pas d’entrée pour ce jour. Une case vide ne dit rien de la journée.","чуть легче":"un peu mieux","без изменений":"sans changement","стало хуже":"c’est pire","без оценки":"non évalué","Удалить разговоры, отметки и заметки дневника из этого браузера? Игровой прогресс останется.":"Supprimer les conversations, relevés et notes du journal de ce navigateur ? La progression des jeux sera conservée.","Скоро":"Bientôt","Ничего не найдено. Попробуй другое слово или состояние.":"Rien trouvé. Essaie un autre mot ou un autre état.","Поддержка":"Soutien","Мне очень жаль, что сейчас так тяжело. Если есть риск причинить себе вред прямо сейчас, позови человека рядом и обратись за срочной помощью по местному экстренному номеру. Ты можешь сказать: «Мне сейчас небезопасно оставаться одной или одному. Побудь со мной и помоги получить помощь».":"Je suis vraiment désolé·e que ce soit si dur en ce moment. S’il y a un risque de te faire du mal maintenant, appelle une personne proche et demande une aide urgente au numéro d’urgence local. Tu peux dire : « Ce n’est pas sûr pour moi de rester seul·e maintenant. Reste avec moi et aide-moi à obtenir de l’aide. »","Показать фразу для близкого":"Afficher un message pour un proche","Можно отправить: «Мне сейчас очень тяжело. Пожалуйста, позвони мне или побудь со мной. Помоги обратиться за помощью».":"Tu peux envoyer : « Ça va vraiment mal en ce moment. S’il te plaît, appelle-moi ou reste avec moi. Aide-moi à demander de l’aide. »","Хорошо, что об этом сказано вслух. Если состояние изменится, обратись к человеку рядом или за срочной помощью.":"C’est bien de l’avoir dit. Si ton état change, tourne-toi vers une personne proche ou demande une aide urgente.","Начнём новый разговор. Как ты сейчас?":"Commençons une nouvelle conversation. Comment vas-tu ?","Рада это слышать. Что сегодня помогло тебе чувствовать себя так?":"Ça me fait plaisir. Qu’est-ce qui t’a aidé·e à te sentir ainsi aujourd’hui ?","Спасибо, что об этом сказано. Что произошло или когда это ощущение появилось? Можно ответить своими словами.":"Merci de l’avoir dit. Que s’est-il passé, ou quand ce sentiment est-il apparu ? Tu peux répondre avec tes mots.","Близкие":"Proches","Не знаю, почему":"Je ne sais pas pourquoi","Понимаю. Насколько сильно это сейчас ощущается — от 1 до 4? Если сложно оценить, можно пропустить.":"Je comprends. À quel point est-ce fort maintenant, de 1 à 4 ? Si c’est difficile à évaluer, tu peux passer.","1 · немного":"1 · un peu","2 · заметно":"2 · nettement","3 · сильно":"3 · fortement","4 · очень сильно":"4 · très fortement","Пропустить":"Passer","Что хочется сделать с этим ощущением?":"Que voudrais-tu faire de ce sentiment ?","Что сейчас было бы нужнее: немного успокоиться, разобраться в ситуации, просто выговориться или отдохнуть?":"De quoi aurais-tu le plus besoin : te calmer un peu, y voir plus clair, simplement vider ton sac ou te reposer ?","Успокоиться":"Me calmer","Разобраться":"Y voir clair","Выговориться":"Vider mon sac","Отдохнуть":"Me reposer","Я слушаю. Расскажи, что было самым неприятным или важным в этом моменте.":"Je t’écoute. Dis-moi ce qui a été le plus désagréable ou le plus important dans ce moment.","Похоже, это действительно задело. Что хотелось бы получить сейчас? Можно выбрать маленький шаг, а можно продолжить разговор.":"On dirait que ça t’a vraiment touché·e. Qu’aimerais-tu maintenant ? Tu peux choisir un petit pas ou continuer à parler.","Рассказать ещё":"En dire plus","Закончить пока":"Arrêter pour l’instant","Я рядом. Что ещё важно сказать?":"Je suis là. Qu’est-ce qui est encore important à dire ?","Спасибо, что поделилась или поделился. Можно вернуться, когда захочешь.":"Merci d’avoir partagé. Tu peux revenir quand tu veux.","Новый разговор":"Nouvelle conversation","Я слушаю. Что хочется рассказать?":"Je t’écoute. Qu’as-tu envie de raconter ?","Спасибо за разговор. Вернись, когда захочешь.":"Merci pour cette conversation. Reviens quand tu veux.","Слышу тебя. Что из этого сейчас важнее всего? Можешь рассказать ещё или выбрать шаг.":"Je t’entends. Qu’est-ce qui compte le plus là-dedans maintenant ? Tu peux en dire plus ou choisir un pas.","Рада, что стало хоть немного легче. Что именно помогло?":"Content·e que ce soit un peu plus léger. Qu’est-ce qui a aidé exactement ?","Жаль, что стало хуже. Остановимся с этой практикой. Сейчас лучше выбрать более мягкую поддержку или обратиться к близкому человеку.":"Désolé·e que ce soit pire. Arrêtons cette pratique. Mieux vaut maintenant choisir un soutien plus doux ou te tourner vers un proche.","Хорошо, что это получилось заметить. Можно попробовать другой шаг или просто остановиться.":"C’est bien de l’avoir remarqué. Tu peux essayer un autre pas ou simplement t’arrêter.","Расскажу ещё":"J’en dirai plus","Я слушаю. Что сейчас на первом плане?":"Je t’écoute. Qu’est-ce qui prend le plus de place maintenant ?","Спасибо за разговор. Береги свой темп.":"Merci pour cette conversation. Prends soin de ton rythme.","Если захочешь, начнём новый разговор.":"Si tu veux, on commence une nouvelle conversation.","Тогда начнём с очень маленькой паузы.":"Alors commençons par une toute petite pause.","Давай отделим то, что произошло, от догадок.":"Séparons ce qui s’est passé des suppositions.","Можно попробовать один из этих шагов. Выбирай только то, что подходит.":"Tu peux essayer un de ces pas. Choisis seulement ce qui te convient.","Хочу рассказать ещё":"Je veux en dire plus","Пока достаточно":"Assez pour l’instant","Как ты после этого шага?":"Comment vas-tu après cette étape ?","Голосовой ввод не поддерживается этим браузером":"La saisie vocale n’est pas prise en charge par ce navigateur","Голосовой ввод недоступен в этом браузере. Можно писать текстом.":"La saisie vocale n’est pas disponible dans ce navigateur. Tu peux écrire.","Распознавание голоса выполняет устройство и может передавать запись его сервису. Продолжить?":"La reconnaissance vocale est faite par l’appareil et peut transmettre l’enregistrement à son service. Continuer ?","Да, включить":"Oui, activer","Остановить запись":"Arrêter l’enregistrement","Слушаю. Фраза появится в поле ввода — проверь её перед отправкой.":"J’écoute. La phrase apparaîtra dans le champ de saisie — vérifie-la avant d’envoyer.","Проверь текст и нажми отправить, когда текст устроит.":"Vérifie le texte et appuie sur envoyer quand il te convient.","Нет доступа к микрофону. Можно продолжить текстом.":"Pas d’accès au micro. Tu peux continuer par écrit.","Не удалось распознать речь. Попробуй ещё раз или напиши текстом.":"Impossible de reconnaître la parole. Réessaie ou écris.","Не удалось включить микрофон.":"Impossible d’activer le micro.","4–6 минут":"4–6 minutes","Небольшая самостоятельная практика после неприятного разговора.":"Une petite pratique à faire seul·e après une conversation désagréable.","После трудного разговора · 4–6 минут":"Après une conversation difficile · 4–6 minutes","«Помоги понять: какой результат ожидается и к какому сроку?»":"« Aide-moi à comprendre : quel résultat est attendu et pour quand ? »","«Мне важно обсудить вопрос, когда мы можем говорить спокойно».":"« C’est important pour moi d’en parler quand on pourra le faire calmement. »","«У меня был трудный разговор. Можешь немного побыть со мной на связи?»":"« J’ai eu une conversation difficile. Tu peux rester un peu en contact avec moi ? »","Шаг {0} из 4":"Étape {0} sur 4","Пауза":"Pause","Результат не оценён. Это тоже нормально.":"Le résultat n’est pas évalué. C’est bien aussi.","Отмечено небольшое облегчение.":"Un petit soulagement est noté.","Стало тяжелее. Эту практику можно оставить и обратиться к человеку, которому доверяешь.":"C’est devenu plus dur. Tu peux laisser cette pratique et te tourner vers une personne de confiance.","Вижу предмет":"Je vois un objet","Слышу звук":"J’entends un son","Чувствую опору":"Je sens un appui","Например: «Руководитель повысил голос и попросил переделать отчёт»":"Par exemple : « Mon responsable a haussé le ton et m’a demandé de refaire le rapport »","Например: «Наверное, я ни на что не способна или не способен»":"Par exemple : « Je ne suis sans doute capable de rien »","Практика пройдена в твоём темпе. Хочешь рассказать ещё или закончить?":"Pratique faite à ton rythme. Tu veux en dire plus ou terminer ?","Отмечено, что стало немного легче. Хочешь остановиться или рассказать, какой шаг оказался выбран?":"C’est noté, c’est un peu plus léger. Tu veux t’arrêter ou dire quel pas tu as choisi ?","Похоже, сейчас стало тяжелее. Остановимся. Можно обратиться к человеку рядом или выбрать другую поддержку.":"On dirait que c’est devenu plus dur. Arrêtons-nous. Tu peux te tourner vers une personne proche ou choisir un autre soutien.","Спасибо за оценку результата. Хочешь рассказать ещё или закончить?":"Merci d’avoir évalué le résultat. Tu veux en dire plus ou terminer ?","тревожно":"anxieux","тяжело":"lourd","злюсь":"en colère","нормально":"ça va","хорошо":"bien","✓ Сделано":"✓ Fait","Скопировано":"Copié","Не удалось":"Échec","Запись о тебе сейчас выключена. Включить её можно в разделе «Обо мне».":"Les notes à ton sujet sont désactivées. Tu peux les activer dans « À propos de moi ».","Такая запись уже есть или список полон.":"Cette entrée existe déjà ou la liste est pleine.","Избранные места":"Lieux favoris","Найденные места":"Lieux trouvés","Выбранный город":"Ville choisie","Счётчики на этом устройстве":"Compteurs sur cet appareil","Цепочки практик":"Enchaînements de pratiques","Согласие на голос":"Consentement vocal","Настройка озвучки":"Réglages de la lecture vocale","Прогресс игр":"Progression des jeux","Прогресс историй":"Progression des histoires","Прогресс квестов":"Progression des quêtes","Не удалось прочитать: это не файл данных «Рядом».":"Lecture impossible : ce n’est pas un fichier de données Ryadom.","Это не файл данных «Рядом».":"Ce n’est pas un fichier de données Ryadom.","В файле нет данных для восстановления.":"Le fichier ne contient pas de données à restaurer.","Пока ничего не сохранено":"Rien n’est encore enregistré","Данные для переноса":"Données à transférer","Выбери, куда сохранить: «Файлы», облако, почта или мессенджер себе.":"Choisis où enregistrer : « Fichiers », le cloud, l’e-mail ou une messagerie vers toi-même.","Не получилось открыть «Поделиться». Воспользуйся кнопкой «Скопировать текст».":"Impossible d’ouvrir « Partager ». Utilise le bouton « Copier le texte ».","Файл сохраняется. Если ничего не произошло — воспользуйся кнопкой «Скопировать текст».":"Enregistrement du fichier. S’il ne se passe rien, utilise le bouton « Copier le texte ».","Не получилось сохранить файл. Воспользуйся кнопкой «Скопировать текст».":"Impossible d’enregistrer le fichier. Utilise le bouton « Copier le texte ».","Скопировано. Вставь в заметки или сообщение себе.":"Copié. Colle-le dans tes notes ou dans un message à toi-même.","Скопировать автоматически не вышло. Текст выделен — скопируй его вручную.":"La copie automatique a échoué. Le texte est sélectionné — copie-le à la main.","Файл слишком большой.":"Le fichier est trop volumineux.","Вставь сюда скопированный текст и нажми кнопку ещё раз":"Colle ici le texte copié et appuie de nouveau sur le bouton","Всё удалено. Обновляю приложение…":"Tout est supprimé. Rechargement de l’application…","Где хранятся":"Où c’est stocké","Что передаётся наружу":"Ce qui est envoyé à l’extérieur","Что приложение не делает":"Ce que l’application ne fait pas","Важно":"Important","Новых мест для добавления нет. Отметь любимые в разделе «Места» или посещения в дневнике.":"Aucun nouveau lieu à ajouter. Marque tes favoris dans « Lieux » ou tes visites dans le journal.","Сейчас записи не используются: ни в разговоре, ни в подсказках, ни на сервере.":"Les notes ne sont pas utilisées pour l’instant : ni dans la conversation, ni dans les suggestions, ni sur le serveur.","Романтично":"Romantique","Весело":"Amusant","Хочется нового":"Envie de nouveauté","Устало":"Fatigué","Хочется общения":"Envie de compagnie","Расстояние неизвестно":"Distance inconnue","Сад":"Jardin","Библиотека":"Bibliothèque","Музей":"Musée","Смотровая площадка":"Point de vue","Ресторан":"Restaurant","Галерея":"Galerie","Кинотеатр":"Cinéma","Театр":"Théâtre","Достопримечательность":"Site touristique","Арт-пространство":"Espace d’art","Книжный магазин":"Librairie","Бар":"Bar","Уже есть в твоём дневнике":"Déjà dans ton journal","Отметок об этом месте в дневнике: {0}":"Mentions de ce lieu dans le journal : {0}","Любимое место · под выбранное настроение может подойти другое":"Lieu favori · un autre pourrait mieux convenir à l’humeur choisie","На карте ↗":"Sur la carte ↗","Была/был здесь":"J’y suis allé·e","01 / ТВОИ МЕСТА":"01 / TES LIEUX","Любимые сначала":"Favoris d’abord","02 / ПОБЛИЗОСТИ":"02 / À PROXIMITÉ","Новые места рядом":"Nouveaux lieux à proximité","Показано {0} мест рядом с «{1}».":"{0} lieux affichés près de « {1} ».","Найдено {0} мест в радиусе около 2 км. Данные OpenStreetMap могут быть неполными.":"{0} lieux trouvés dans un rayon d’environ 2 km. Les données OpenStreetMap peuvent être incomplètes.","Поблизости пока не нашлось мест под это настроение. Попробуй другой район или настроение.":"Pas encore de lieux à proximité pour cette humeur. Essaie un autre quartier ou une autre humeur.","Поиск новых мест сейчас недоступен. Любимые места из дневника остаются здесь. Попробуй позже или укажи другой район.":"La recherche de nouveaux lieux est indisponible pour l’instant. Les lieux favoris du journal restent ici. Réessaie plus tard ou choisis un autre quartier.","Этот браузер не поддерживает определение местоположения. Введи город вручную.":"Ce navigateur ne prend pas en charge la localisation. Saisis une ville à la main.","Запрашиваем местоположение…":"Demande de localisation…","текущей точки":"position actuelle","Не удалось получить местоположение. Введи город или район вручную.":"Impossible d’obtenir la position. Saisis une ville ou un quartier à la main.","Не удалось найти этот город или район. Попробуй уточнить название.":"Impossible de trouver cette ville ou ce quartier. Essaie de préciser le nom.","Не удалось найти город сейчас. Попробуй ещё раз позже или используй геолокацию.":"Impossible de trouver la ville pour l’instant. Réessaie plus tard ou utilise la localisation.","Убрать из любимых":"Retirer des favoris","Изменить место":"Changer de lieu","Или выбери любимое:":"Ou choisis un favori :","Ты":"Toi","МЕНЮ":"MENU","Попробовать ещё раз":"Réessayer","Дальше →":"Suivant →","Скопировать":"Copier","Сначала напиши свою версию.":"Écris d’abord ta version.","Скопировано.":"Copié.","Скопируй текст вручную.":"Copie le texte à la main.","Запомнить в «Обо мне»":"Garder dans « À propos de moi »","Записано в «Обо мне».":"Enregistré dans « À propos de moi ».","К играм":"Vers les jeux","Озвучка ответов включена":"Lecture vocale des réponses activée","Озвучка включена.":"Lecture vocale activée.","Данные «Рядом»":"Données Ryadom","Копия данных приложения «Рядом». Храни её в надёжном месте.":"Copie des données de l’application Ryadom. Conserve-la en lieu sûr.","Сохранить копию":"Enregistrer une copie","Как ты сегодня? Можно отметить состояние за минуту.":"Comment vas-tu aujourd’hui ? Tu peux noter ton état en une minute.","Минутка для себя: как прошёл день?":"Une minute pour toi : comment s’est passée ta journée ?","Если день был непростым — я рядом. Можно просто отметить настроение.":"Si la journée a été difficile, je suis là. Tu peux juste noter ton humeur.","Напоминания недоступны на этом устройстве.":"Les rappels ne sont pas disponibles sur cet appareil.","Напоминание выключено.":"Rappel désactivé.","Уведомления запрещены. Их можно разрешить в настройках телефона для приложения «Рядом».":"Les notifications sont bloquées. Tu peux les autoriser dans les réglages du téléphone pour l’app Ryadom.","Напоминание":"Rappel","Раз в день мягко напомню отметить состояние. Работает без интернета, ничего никуда не отправляется.":"Une fois par jour, je te rappellerai doucement de noter ton état. Fonctionne hors ligne, rien n’est envoyé.","Ежедневное напоминание":"Rappel quotidien","Каждый день":"Chaque jour","Время напоминания":"Heure du rappel","Похоже, сейчас тревожно.":"On dirait que tu es anxieux·se en ce moment.","Похоже, сейчас грустно.":"On dirait que tu es triste en ce moment.","Похоже, сейчас много злости.":"On dirait qu’il y a beaucoup de colère en ce moment.","Похоже, сил сейчас совсем немного.":"On dirait que tu as très peu d’énergie en ce moment.","Похоже, сейчас одиноко.":"On dirait que tu te sens seul·e en ce moment.","Похоже, это задело.":"On dirait que ça t’a blessé·e.","Похоже, рядом с этим есть чувство вины или стыда.":"On dirait qu’il y a de la culpabilité ou de la honte avec ça.","Как хорошо это слышать!":"Ça fait du bien d’entendre ça !","Слышу, что это связано с работой.":"J’entends que c’est lié au travail.","Слышу, что это связано с семьёй.":"J’entends que c’est lié à la famille.","Слышу, что это связано с отношениями.":"J’entends que c’est lié à ta relation.","Слышу, что это связано с друзьями.":"J’entends que c’est lié aux amis.","Слышу, что это связано со здоровьем.":"J’entends que c’est lié à la santé.","Слышу, что это связано с деньгами.":"J’entends que c’est lié à l’argent.","Слышу, что это связано с учёбой.":"J’entends que c’est lié aux études.","Я слушаю. Что было дальше?":"Je t’écoute. Que s’est-il passé ensuite ?","Это звучит непросто. Что сейчас ощущается сильнее всего?":"Ça a l’air difficile. Qu’est-ce que tu ressens le plus fort maintenant ?","Понимаю. Что для тебя здесь самое важное?":"Je comprends. Qu’est-ce qui est le plus important pour toi ici ?","Спасибо, что рассказываешь. Как это на тебя повлияло?":"Merci de me le raconter. Comment cela t’a-t-il affecté·e ?","Если посмотреть на это со стороны — что хотелось бы изменить в первую очередь?":"Si tu regardes cela de l’extérieur, que voudrais-tu changer en premier ?","Что помогло бы тебе хоть немного прямо сейчас?":"Qu’est-ce qui t’aiderait, même un peu, maintenant ?","Злюсь":"En colère","Одиноко":"Seul·e","Всё хорошо":"Tout va bien","Куда сегодня сходить?":"Où aller aujourd’hui ?","Просто выговориться":"Juste vider mon sac","Небольшой шаг, чтобы стало легче":"Un petit pas pour aller mieux","Потренировать трудный разговор":"M’entraîner à une conversation difficile","Куда сходить или что поесть":"Où aller ou quoi manger","Привет. Я — «Рядом». Можно написать, как ты, своими словами или выбрать подсказку.":"Salut. Je suis Ryadom. Tu peux écrire comment tu vas avec tes mots ou choisir une suggestion.","На этом языке я понимаю простые фразы. Подсказки-кнопки помогут быть точнее.":"Dans cette langue, je comprends des phrases simples. Les boutons de suggestion aident à être plus précis.","Как хорошо это слышать! Что сегодня порадовало?":"Ça fait du bien d’entendre ça ! Qu’est-ce qui t’a fait plaisir aujourd’hui ?","Куда сходить отметить?":"Où aller pour fêter ça ?","Записать в дневник":"Écrire dans le journal","Есть и сложная часть":"Il y a aussi une partie difficile","Что сейчас было бы полезнее?":"Qu’est-ce qui serait le plus utile maintenant ?","Вот что можно попробовать. Любой шаг можно остановить.":"Voici ce que tu peux essayer. Tu peux arrêter n’importe quel pas.","Лучше просто поговорим":"Parlons simplement","Подобрать небольшой шаг":"Trouver un petit pas","Продолжу рассказывать":"Je continue à raconter","Спасибо за разговор. Я здесь, когда захочется вернуться.":"Merci pour cette conversation. Je suis là quand tu voudras revenir.","Начать новый разговор":"Commencer une nouvelle conversation","Открыть дневник":"Ouvrir le journal","Похоже, сейчас очень много злости. Если есть риск навредить другому человеку — остановись и выйди из ситуации: на воздух, в другую комнату. Если опасность рядом — звони в экстренную службу.":"On dirait qu’il y a beaucoup de colère en ce moment. S’il y a un risque de faire du mal à quelqu’un, arrête-toi et sors de la situation : dehors ou dans une autre pièce. S’il y a un danger, appelle les secours.","То, что ты описываешь, звучит небезопасно. Твоя безопасность важнее всего. Если опасность рядом прямо сейчас — постарайся уйти в безопасное место и позвони в экстренную службу.":"Ce que tu décris semble dangereux. Ta sécurité compte avant tout. Si le danger est proche maintenant, essaie d’aller dans un endroit sûr et appelle les secours.","Спасибо, что ты об этом говоришь. Твоя безопасность сейчас важнее всего. С этим не нужно справляться без поддержки: позвони на линию помощи или человеку, которому доверяешь.":"Merci de m’en parler. Ta sécurité compte avant tout maintenant. Tu n’as pas à affronter ça sans soutien : appelle une ligne d’écoute ou une personne de confiance.","Показать текст для близкого":"Afficher un texte pour un proche","Сейчас я в безопасности":"Je suis en sécurité maintenant","Если опасность прямо сейчас — экстренная служба: 112 (в большинстве стран).":"En cas de danger immédiat — numéro d’urgence : 112 (dans la plupart des pays).","Линии помощи в других странах: findahelpline.com":"Lignes d’écoute dans d’autres pays : findahelpline.com","Пожалуйста. Я рядом.":"Avec plaisir. Je suis là.","Нет, я не врач и не психолог: не ставлю диагнозов и не лечу. Я помогаю выговориться, назвать, что происходит, и сделать небольшой шаг. Если тяжёлое состояние держится долго или мешает жить, стоит обратиться к специалисту.":"Non, je ne suis ni médecin ni psychologue : je ne pose pas de diagnostic et je ne soigne pas. J’aide à vider ton sac, à nommer ce qui se passe et à faire un petit pas. Si un état difficile dure ou gêne ta vie, mieux vaut consulter un spécialiste.","Я «Рядом» — программа, а не человек. Я не врач и не заменяю специалиста.":"Je suis Ryadom — un programme, pas une personne. Je ne suis pas médecin et je ne remplace pas un spécialiste.","Хорошо, не будем. Ничего объяснять не нужно. Можно просто побыть рядом или выбрать другое.":"D’accord, on ne le fera pas. Tu n’as rien à expliquer. On peut juste être là ou choisir autre chose.","Я рядом. Начнём с самого простого: что сейчас ближе?":"Je suis là. Commençons par le plus simple : qu’est-ce qui est le plus proche de ce que tu vis ?","Привет. Что сейчас происходит? Можно написать своими словами или выбрать подсказку.":"Salut. Que se passe-t-il en ce moment ? Tu peux écrire avec tes mots ou choisir une suggestion.","Это стоит запомнить. Хочешь отметить это — сходить куда-нибудь или записать в дневник?":"Ça vaut la peine de s’en souvenir. Tu veux le marquer — sortir quelque part ou l’écrire dans le journal ?","А что здесь сильнее всего?":"Et qu’est-ce qui est le plus fort ici ?","Обида":"Blessure","Усталость":"Fatigue","Хочу понять точнее. Что ближе всего к тому, что сейчас внутри? Можно выбрать подсказку.":"Je veux mieux comprendre. Qu’est-ce qui est le plus proche de ce que tu ressens ? Tu peux choisir une suggestion.","Из того, что известно о тебе:":"D’après ce que je sais de toi :","В разделе «Места» можно выбрать настроение и посмотреть, что рядом.":"Dans « Lieux », tu peux choisir une humeur et voir ce qu’il y a autour.","Открыть «Места»":"Ouvrir « Lieux »","Расскажу, что на душе":"Je vais dire ce que j’ai sur le cœur","Расскажи, что ещё происходит.":"Dis-moi ce qui se passe d’autre.","Я слушаю. Можно писать как получается — кусками, без порядка.":"Je t’écoute. Tu peux écrire comme ça vient — par morceaux, sans ordre.","Тренажёры трудных разговоров пока доступны только на русском языке. Можно открыть их или выбрать другое.":"Les entraînements aux conversations difficiles ne sont pour l’instant disponibles qu’en russe. Tu peux les ouvrir ou choisir autre chose.","Открыть тренажёры":"Ouvrir les entraînements","Я слушаю.":"Je t’écoute.","Хорошо. Если станет хуже — линии помощи выше, и можно вернуться сюда в любой момент.":"D’accord. Si ça empire, les lignes d’écoute sont plus haut, et tu peux revenir ici à tout moment.","Можно отправить близкому:":"Tu peux envoyer à un proche :","Мне сейчас очень тяжело. Пожалуйста, побудь со мной или позвони мне сейчас. Помоги обратиться за помощью.":"Ça va vraiment mal en ce moment. S’il te plaît, reste avec moi ou appelle-moi maintenant. Aide-moi à demander de l’aide.","Хорошо, что стало хоть немного легче. Хочешь остановиться на этом или продолжить?":"C’est bien que ce soit un peu plus léger. Tu veux t’arrêter là ou continuer ?","Жаль, что стало тяжелее. Давай не продолжать эту практику. Можно связаться с близким человеком или выбрать другой, более мягкий шаг.":"Désolé·e que ce soit plus dur. Ne continuons pas cette pratique. Tu peux contacter un proche ou choisir un autre pas, plus doux.","Иногда эффект приходит не сразу. Можно попробовать другой способ или просто поговорить.":"Parfois l’effet ne vient pas tout de suite. Tu peux essayer une autre façon ou simplement parler.","Другой способ":"Une autre façon","Подобрано {x}. Можно выбрать любое или ничего.":"Sélection : {x}. Tu peux en choisir un ou aucun.","по последней отметке «{q}»":"d’après ton dernier relevé « {q} »","по последней отметке «{q}» и позднему времени":"d’après ton dernier relevé « {q} » et l’heure tardive","{x} · Открыть →":"{x} · Ouvrir →","{0} из {1}":"{0} sur {1}","Отметить шаг цепочки: {x}":"Marquer l’étape : {x}","Открыть практику: {x}":"Ouvrir la pratique : {x}","Открыть тренажёр: {x}":"Ouvrir l’entraînement : {x}","Убрать «{q}»":"Retirer « {q} »","Удалить: {x}":"Supprimer : {x}","Идея на сегодня: {x}.":"Idée pour aujourd’hui : {x}.","Идея на сегодня: {x}. Лучше без: {y}.":"Idée pour aujourd’hui : {x}. Plutôt sans : {y}.","поесть":"manger","побыть":"passer du temps","{0} Б":"{0} o","{0} КБ":"{0} Ko","Данные восстановлены ({0}). Обновляю приложение…":"Données restaurées ({0}). Rechargement de l’application…","Добавлено записей: {0}":"Entrées ajoutées : {0}","тебе обычно подходит — {x}. Выбирай места с учётом этого.":"ce qui te convient d’habitude — {x}. Choisis tes lieux en en tenant compte.","тебе обычно подходит — {x}. Лучше без: {y}. Выбирай места с учётом этого.":"ce qui te convient d’habitude — {x}. Plutôt sans : {y}. Choisis tes lieux en en tenant compte.","{0} м":"{0} m","{0} км":"{0} km","Убрать из любимых: {x}":"Retirer des favoris : {x}","В любимые: {x}":"Ajouter aux favoris : {x}","«{q}» добавлено в дневник за сегодня.":"« {q} » ajouté au journal d’aujourd’hui.","Ищем места рядом с «{q}»…":"Recherche de lieux près de « {q} »…","Ищем «{q}»…":"Recherche de « {q} »…","Сохранён город «{q}». Выбирай настроение — подборка обновится.":"Ville « {q} » enregistrée. Choisis une humeur — la sélection se mettra à jour.","Найдено практик: {0} из {1}":"Pratiques trouvées : {0} sur {1}","Показать ещё ({0})":"Afficher plus ({0})","В диалоге: {x}":"Dans la conversation : {x}","Удалить тексты разговоров за {x}? Отметки состояния останутся.":"Supprimer les textes des conversations du {x} ? Les relevés d’état resteront.","Практики: {x}":"Pratiques : {x}","Шаг {0} из {1}":"Étape {0} sur {1}","Подсказка: {x}":"Indice : {x}","Источник: {x}":"Source : {x}","Пройдено стилей: {0} из {1}":"Styles terminés : {0} sur {1}","День {0}":"Jour {0}","{x} по дням":"{x} par jour","Готово: каждый день в {0}:{1}. Пропускать можно — это просто приглашение.":"C’est fait : chaque jour à {0}:{1}. Tu peux sauter — c’est juste une invitation.","Чаще всего тебе помогала практика «{q}» ({0} раз). Это личная заметка, не медицинский вывод.":"La pratique qui t’a le plus souvent aidé·e : « {q} » ({0} fois). C’est une note personnelle, pas une conclusion médicale.","Удалить «{q}» из этого дня?":"Retirer « {q} » de ce jour ?","{0} место":"{0} lieu","{0} места":"{0} lieux","{0} мест":"{0} lieux","Играть: {x}":"Jouer : {x}","{0} мин":"{0} min","{0} минуты":"{0} minutes","{0} минут":"{0} minutes","{0} минута":"{0} minute","{0}–{1} минут":"{0}–{1} minutes","рядом":"ryadom","Я":"Moi","на каждый день":"pour chaque jour","← К играм":"← Vers les jeux",". Оценки и популярность в соцсетях появятся только после подключения проверенного источника данных.":". Les notes et la popularité sur les réseaux sociaux n’apparaîtront qu’après la connexion d’une source de données vérifiée.","есть разговор":"conversation enregistrée","есть отметка состояния":"état noté","есть посещённые места":"lieux visités","Квесты и сюжетные игры пока доступны только на русском языке. Перевод появится в следующих версиях.":"Les quêtes et les jeux narratifs ne sont pour l’instant disponibles qu’en russe. La traduction arrivera dans les prochaines versions.","Не знаю, как сказать":"Je ne sais pas comment le dire","Если сейчас очень тяжело":"Si c’est très dur en ce moment","С этим не нужно справляться в одиночку. Выбери то, что получится сейчас.":"Tu n’as pas à affronter ça seul·e. Choisis ce qui est possible maintenant.","Позвонить":"Appeler","Написать близкому":"Écrire à un proche","Мне сейчас очень тяжело. Пожалуйста, позвони мне или побудь рядом. Помоги мне получить помощь.":"Ça va vraiment mal en ce moment. S’il te plaît, appelle-moi ou reste avec moi. Aide-moi à obtenir de l’aide.","Пережить ближайшие минуты":"Traverser les prochaines minutes","Медленный выдох длиннее вдоха. Назови пять вещей, которые видишь вокруг. Если рядом есть что-то опасное — отложи это подальше или выйди в другое место.":"Expire lentement, plus longtemps que l’inspiration. Nomme cinq choses que tu vois autour de toi. S’il y a quelque chose de dangereux près de toi, éloigne-le ou va ailleurs.","Дыхание вместе со мной":"Respire avec moi","Мой план безопасности":"Mon plan de sécurité","Заполни, когда немного спокойнее. План останется только на этом устройстве и откроется здесь в трудную минуту.":"Remplis-le quand tu es un peu plus calme. Le plan reste uniquement sur cet appareil et s’ouvrira ici dans un moment difficile.","Как я понимаю, что мне становится хуже":"À quoi je vois que ça empire","Что помогает мне хоть немного":"Ce qui m’aide, même un peu","Кому могу написать или позвонить":"Qui je peux contacter ou appeler","Как сделать обстановку вокруг безопаснее":"Comment rendre mon environnement plus sûr","«Рядом» — не экстренная служба и может не распознать, что тебе плохо. Если есть риск для жизни, звони 112 или обратись к человеку рядом.":"Ryadom n’est pas un service d’urgence et peut ne pas reconnaître que tu vas mal. En cas de danger pour la vie, appelle le 112 ou tourne-toi vers une personne proche.","Мне очень плохо":"Ça va très mal","Мне сейчас очень плохо — открыть помощь":"Ça va très mal maintenant — ouvrir l’aide","Открыть экран помощи":"Ouvrir l’écran d’aide","Прежде чем продолжить, хочу спросить прямо, потому что это важно: ты сейчас думаешь о том, чтобы причинить себе вред или не жить?":"Avant de continuer, je veux te demander directement, parce que c’est important : est-ce que tu penses en ce moment à te faire du mal ou à ne plus vivre ?","Да":"Oui","Не знаю":"Je ne sais pas","Нет, это другое":"Non, c’est autre chose","Спасибо за ответ. Продолжим.":"Merci pour ta réponse. Continuons."},"lex":{"emo":{"fear":["anxi","inqui","peur","stress","angoiss","panique","nerveu"],"sad":["triste","pleur","déprim","deprim","cafard","chagrin"],"anger":["colère","colere","énerv","enerv","furieu","rage","agac","déteste"],"tired":["fatigu","épuis","epuis","crevé","creve","plus d’énergie","sans énergie","burn"],"lonely":["seul","personne","isolé","isole"],"hurt":["bless","vexé","vexe","trahi","humili","offens"],"shame":["honte","coupable","culpabil","gêne","gene"],"good":["bien","super","heureu","content","joie","calme","mieux","génial"]},"theme":{"work":["travail","boulot","patron","chef","bureau","collègue","collegue"],"family":["famille","maman","papa","mère","mere","père","pere","parents","frère","frere","sœur","soeur","fils","fille"],"love":["copain","copine","mari","femme","partenaire","couple","relation","rupture"],"friends":["ami ","amie","amis","pote"],"health":["santé","sante","malade","douleur","médecin","medecin","hôpital"],"money":["argent","dette","salaire","loyer","factures","crédit"],"study":["école","ecole","examen","étud","etud","université","fac","cours","prof"]},"intent":{"bye":["au revoir","bonne nuit","à plus","salut !"],"thanks":["merci"],"doctor":["es-tu médecin","tu es médecin","psycholog","thérapeute"],"who":["qui es-tu","tu es qui","es-tu humain","un robot","un bot"],"hello":["bonjour","salut","coucou"],"help":["aide-moi","aidez-moi","que faire"],"go":["où aller","ou aller","sortir","quoi manger"],"nowant":["je ne veux pas","veux pas","laisse-moi","arrête"]}},"help":{"lines":["France : 3114 (prévention du suicide)"]}};
